import{ARENA_GROWTH}from'./path-growth.js';
import{icon}from'./ui-icons.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const ORDER=['gryffindor','hufflepuff','slytherin','ravenclaw'];
const ELEMENTS={gryffindor:['#ff9d64','#e56337','Fire lion'],hufflepuff:['#f6d97e','#ddb344','Air bear'],slytherin:['#aad98b','#6eb274','Nature snake'],ravenclaw:['#82d9ec','#42accb','Water eagle']};
export function teamBadge(id){const[a,b]=ELEMENTS[id]||ELEMENTS.hufflepuff,symbol={gryffindor:'M20 11c2 7-7 6-3 13-3-1-4-4-4-4-5 8-1 15 7 15 11 0 14-12 0-24Z',hufflepuff:'M10 20h17c7 0 7-9 1-9-4 0-5 3-4 5M9 26h24M11 32h13c6 0 7 8 1 8-3 0-4-2-3-4',slytherin:'M12 33C12 15 25 15 34 12c1 13-4 24-17 23m-2-3 14-14',ravenclaw:'M23 10C20 16 12 22 12 29a11 11 0 0 0 22 0c0-7-8-13-11-19m-5 17c-1 5 1 7 4 7'}[id];return`<svg class="team-shield" viewBox="0 0 46 52" aria-hidden="true"><path d="M23 3 42 10v17c0 11-10 18-19 23C14 45 4 38 4 27V10Z" fill="${b}" stroke="#1b294f" stroke-width="3"/><path d="m23 9 13 5v12c0 8-6 14-13 18-7-4-13-10-13-18V14Z" fill="${a}"/><path d="${symbol}" fill="${id==='hufflepuff'?'none':'#fffdf0'}" stroke="${id==='hufflepuff'?'#fffdf0':'none'}" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/></svg>`;}
const chevron='<svg class="launch-chevron" viewBox="0 0 12 20" aria-hidden="true"><path d="m3 3 5 7-5 7" fill="none" stroke="currentColor" stroke-width="4" stroke-linecap="round" stroke-linejoin="round"/></svg>',play='<svg viewBox="0 0 28 32" aria-hidden="true"><path d="M4 3v26L26 16Z" fill="currentColor" stroke="currentColor" stroke-width="4" stroke-linejoin="round"/></svg>',lock='<svg viewBox="0 0 32 38" aria-hidden="true"><path d="M7 16V11a9 9 0 0 1 18 0v5" fill="none" stroke="currentColor" stroke-width="5"/><rect x="2" y="15" width="28" height="22" rx="4" fill="currentColor"/></svg>';
function arenaCard(a,i){const status=a.locked?'Locked':a.completed?'Completed':a.progress?`${a.progress}/20 checkpoints`:'Ready to explore';return`<button type="button" class="launch-arena ${a.selected?'is-selected':''} ${a.locked?'is-locked':''} ${a.completed?'is-complete':''}" data-do="area" data-area="${i}" aria-pressed="${a.selected}" aria-label="${esc(a.name)}, ${esc(status)}${a.locked?'. Complete the previous guardian to unlock.':''}" ${a.locked?'disabled aria-disabled="true"':''}><img class="arena-scenery" src="assets/menu/arena-${i}.svg" alt=""><span class="arena-shade"></span>${a.locked?`<span class="arena-lock">${lock}</span>`:''}<span class="arena-caption"><strong>${esc(a.name)}</strong><small>${a.completed?icon('check'):''}${esc(status)}</small></span>${a.selected?`<span class="arena-selected" aria-hidden="true">${icon('check')}</span>`:''}</button>`;}
export function launchMarkup(c){const primary=c.firstLaunch?'go':c.completed?'lessons':c.nextArea!=null?'next-area':'enter',label=c.firstLaunch?'PLAY':c.completed?'Choose a new journey':c.nextArea!=null?'Explore '+c.nextAreaTitle:c.guardian?'Challenge guardian':c.resume?'Continue expedition':'PLAY';return`<div class="launch-shell"><section class="launch-panel" aria-label="Expedition setup"><header class="launch-header"><div><span class="launch-kicker">YOUR NEXT ADVENTURE</span><h1>Ready to explore?</h1></div><button type="button" class="launch-wallet" data-do="trails" aria-label="Wardrobe, ${c.coins} coins">${icon('coin')}<b>${c.coins}</b></button></header><div class="launch-body"><section class="launch-arenas" aria-labelledby="arena-label"><div class="launch-section-label"><h2 id="arena-label">ARENA</h2><span>${c.areas.filter(a=>!a.locked).length} / 3 unlocked</span></div><div class="launch-arena-grid">${c.areas.map(arenaCard).join('')}</div><p class="arena-unlock-note">${(()=>{const i=Math.max(0,c.areas.findIndex(a=>a.selected)),p=ARENA_GROWTH[i];return `Forms ${p.start}–${p.boss} · Boss victory earns Form ${p.boss}.`;})()}<br>${c.areas.some(a=>a.locked)?'Complete an arena and its guardian to unlock the next.':'All three arenas unlocked.'}</p></section><section class="launch-teams" aria-labelledby="team-label"><div class="launch-section-label"><h2 id="team-label">TEAM</h2><button type="button" class="launch-nickname" data-do="rename" aria-label="Rename ${esc(c.nickname)}">${esc(c.nickname)} · Form ${c.level} ${icon('edit')}</button></div><div class="launch-team-grid" role="group" aria-label="Who will you explore with?">${ORDER.map(id=>c.partners.find(p=>p.id===id)).filter(Boolean).map(p=>`<button type="button" class="launch-team ${p.selected?'is-selected':''}" data-do="partner" data-partner="${p.id}" aria-pressed="${p.selected}" aria-label="${esc(p.name)}, ${esc(p.element.toUpperCase())}, ${esc(ELEMENTS[p.id][2])}, Form ${p.level??0}"><span class="launch-team-art"><img src="${esc(p.portrait)}" alt="">${teamBadge(p.id)}</span><strong>${esc(p.name)}</strong><small>${esc(p.element)} · Form ${p.level??0}</small></button>`).join('')}</div></section><div class="launch-selection"><section class="launch-lesson"><div class="launch-section-label"><h2>LESSON</h2></div><button type="button" class="launch-lesson-button" data-do="lessons" aria-label="Change lesson: Grade ${c.grade}, ${esc(c.unitTitle)}"><span class="launch-grade-number">${c.grade}</span><span class="launch-lesson-copy"><small>GRADE ${c.grade} · ${c.lessonKind||'UNIT'} ${c.unitNumber||1}</small><strong>${esc(c.unitTitle)}</strong></span>${chevron}</button></section><section class="launch-pace"><div class="launch-section-label"><h2>PACE</h2></div><div class="launch-mode-switch" role="group" aria-label="Difficulty">${['relaxed','challenge'].map(m=>`<button type="button" data-do="mode" data-mode="${m}" aria-pressed="${m===c.mode}" class="${m===c.mode?'is-selected':''}">${m==='relaxed'?'Relaxed':'Challenge'}</button>`).join('')}</div></section></div></div><footer class="launch-footer"><button type="button" class="launch-play ${c.resume&&!c.completed&&c.nextArea==null?'is-resume':''}" data-do="${primary}"><span>${esc(label)}</span>${play}</button>${c.resume&&!c.completed&&c.nextArea==null?`<p class="launch-checkpoint">${icon('check')} Saved checkpoint · ${c.progress||0}/20 activities · ${esc(c.areaName)}</p>`:''}<div class="launch-footer-links"><button type="button" data-do="journal">${icon('book')} Practice journal</button><span>Team progress saves on this device</span>${c.install?`<button type="button" class="launch-install" data-do="install">${icon('download')} Install</button>`:''}<button type="button" class="launch-help" data-do="help" aria-label="How to play">${icon('help')}</button></div></footer></section></div>`;}
export function lessonMarkup({grade,units,journeys,selected,teamName,topics={}}){return`<div class="lesson-browser-body"><div class="lesson-grade-grid" role="group" aria-label="Choose grade">${[5,6,7,8].map(g=>`<button type="button" class="lesson-grade ${g===grade?'is-selected':''}" data-do="grade" data-grade="${g}" aria-pressed="${g===grade}"><small>GRADE</small><b>${g}</b><span>${{5:'Maarif · A2.1',6:'Maarif · A2.2',7:'MEB · A2',8:'MEB · A2'}[g]}</span></button>`).join('')}</div><p class="lesson-browser-hint">Choose any ${grade<7?'theme':'unit'}. ${teamName?esc(teamName)+' · ':''}Progress is saved separately for each team and lesson.</p><div class="lesson-browser-list">${units.filter(u=>u.grade===grade).map((u,i)=>{const j=journeys[u.id],done=j?.guardians||[],chosen=u.id===selected;return`<button type="button" class="lesson-row ${chosen?'is-selected':''}" data-do="unit" data-unit="${u.id}" aria-pressed="${chosen}"><span class="lesson-number">${i+1}</span><span class="lesson-row-copy"><strong>${esc(u.title)}</strong><small>${u.curriculum?.kind==='enrichment'?'Enrichment · ':''}${esc(topics[u.id]||'Vocabulary, sentences and everyday English')}</small><span class="lesson-progress">${j?`Form ${j.level} · ${done.length}/3 arenas complete`:'New journey · Form 0'}</span></span><span class="lesson-stars" role="img" aria-label="${done.length} of 3 arenas complete">${[0,1,2].map(a=>`<i class="${done.includes(a)?'earned':''}">${icon('star')}</i>`).join('')}</span>${chosen?`<span class="lesson-chosen" aria-hidden="true">${icon('check')}</span>`:''}</button>`;}).join('')}</div></div>`;}
